







































import Vue from "vue";
import ProjectDetailsOverlay from "@/components/ProjectDetailsOverlay.vue";
import ProjectData from "@/data/ProjectData";

export default Vue.extend({
  name: "ProjectsList",
  components: {
    ProjectDetailsOverlay,
  },
  props: {
    projects: Array,
    enableImageFullscreen: {
      type: Boolean,
      default: false,
    },
  },
  data: function () {
    return {
      showPopup: false,
      popupTitle: "",
      popupColor: "",
      popupContent: "",
      isFullscreen: false,
      fullscreenUrl: "",
    };
  },
  methods: {
    showDetails: function (item: ProjectData) {
      if (this.enableImageFullscreen) {
        // open the project's thumbnail in fullscreen
        this.enterFullscreen(item.iconUrl);
        return;
      }

      this.popupTitle = item.name;
      this.popupColor = item.accentColor;
      this.popupContent = item.htmlDescription;
      this.showPopup = true;
      window.scrollTo(0,0);
    },
    enterFullscreen(url: string) {
      this.fullscreenUrl = url;
      this.isFullscreen = true;
      document.body.style.overflow = 'hidden';
    },
    exitFullscreen() {
      this.isFullscreen = false;
      this.fullscreenUrl = '';
      document.body.style.overflow = '';
    },
    handleKeydown(event: KeyboardEvent) {
      if (this.isFullscreen && event.key === 'Escape') {
        this.exitFullscreen();
      }
    }
  },
  mounted() {
    window.addEventListener('keydown', this.handleKeydown);
  },
  beforeDestroy() {
    window.removeEventListener('keydown', this.handleKeydown);
    document.body.style.overflow = '';
  }
});
